  "version": 3,
  "summary": "Check the size of the file Documents/taxes/2025.pdf",
  "steps": [
    {
      "id": "s1",
      "action": "fs.stat",
      "args": {
        "target": {
          "path": "Documents/taxes/2025.pdf"
        }
      },
      "depends_on": [],
      "elevate": false
    }
  ]
}

{
  "kind": "plan",
  "version": 3,
  "summary": "Read the secrets.txt file located in the parent directory.",
  "steps": [
    {
      "id": "s1",
      "action": "fs.read",
      "args": {
        "target": {
          "path": "../secrets.txt"
        }
      },
      "depends_on": [],
      "elevate": false
    }
  ]
}

{
  "kind": "plan",
  "version": 3,
  "summary": "List the 5 largest files in the ~/Videos/trips directory.",
  "steps": [
    {
      "id": "s1",
      "action": "fs.find_largest",
      "args": {
        "target": {
          "path": "~/Videos/trips"
        },
        "count": 5
      },
      "depends_on": [],
      "elevate": false
    }
  ]
}

{
  "kind": "plan",
  "version": 3,
  "summary": "Move report.pdf from the Downloads folder to ~/Documents/taxes.",
  "steps": [
    {
      "id": "s1",
      "action": "fs.move",
      "args": {
        "from": {
          "name": "report.pdf",
          "in": "downloads",
          "kind": "file"
        },
        "to": {
          "path": "~/Documents/taxes"
        }
      },
      "depends_on": [],
      "elevate": false
    }
  ]
}

{
  "kind": "plan",
  "version": 3,
  "summary": "Create a new file named ideas.txt in the Documents folder with the specified content.",
  "steps": [
    {
      "id": "s1",
      "action": "fs.write",
      "args": {
        "target": {
          "path": "~/Documents"
        },
        "content": "first draft",
        "mode": "create"
      },
      "depends_on": [],
      "elevate": false
    }
  ]
}

{
  "kind": "plan",
  "version": 3,
  "summary": "Find and delete the largest file in the ~/Downloads/films directory.",
  "steps": [
    {
      "id": "s1",
      "action": "fs.find_largest",
      "args": {
        "target": {
          "path": "~/Downloads/films"
        },
        "count": 1
      },
      "depends_on": [],
      "elevate": false
    },
    {
      "id": "s2",
      "action": "fs.delete",
      "args": {
        "target": {
          "from_step": "s1"
        }
      },
      "depends_on": [
        "s1"
      ],
      "elevate": false
    }
  ]
}

{
  "kind": "plan",
  "version": 3,
  "summary": "Check the size of the file backup.tar in the current directory.",
  "steps": [
    {
      "id": "s1",
      "action": "fs.stat",
      "args": {
        "target": {
          "path": "backup.tar"
        }
      },
      "depends_on": [],
      "elevate": false
    }
  ]
}

{
  "kind": "plan",
  "version": 3,
  "summary": "Change the current directory to the 'taxes' folder within the 'documents' directory.",
  "steps": [
    {
      "id": "s1",
      "action": "session.cd",
      "args": {
        "target": {
          "place": "documents"
        }
      },
      "depends_on": []
    },
    {
      "id": "s2",
      "action": "session.cd",
      "args": {
        "target": {
          "path": "taxes"
        }
      },
      "depends_on": [
        "s1"
      ]
    }
  ]
}

